CREATE TABLE project_environment_entries(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,environment TEXT NOT NULL CHECK(environment IN ('project','development','preview','production')),kind TEXT NOT NULL CHECK(kind IN ('variable','secret')),ciphertext TEXT NOT NULL,key_version TEXT NOT NULL,version INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,rotated_at INTEGER,deleted_at INTEGER,UNIQUE(project_id,name,environment));
CREATE TABLE environment_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,entry_id TEXT,action TEXT NOT NULL,environment TEXT NOT NULL,entry_version INTEGER,created_at INTEGER NOT NULL,UNIQUE(entry_id,entry_version));
CREATE TRIGGER environment_audit_no_update BEFORE UPDATE ON environment_audit BEGIN SELECT RAISE(ABORT,'immutable_environment_audit'); END;
CREATE TRIGGER environment_audit_no_delete BEFORE DELETE ON environment_audit BEGIN SELECT RAISE(ABORT,'immutable_environment_audit'); END;
CREATE TRIGGER environment_entry_identity BEFORE UPDATE OF project_id,name,environment,kind,created_by,created_at ON project_environment_entries BEGIN SELECT RAISE(ABORT,'immutable_environment_identity'); END;
